// 人物卡PC03实源门：两次不同采购的受领、买粮、交付回报和冷恢复均走正常World入口。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;namespace fs=std::filesystem;Integer checks=0;V::Array trace;
void check(bool value,const StableId& label){++checks;if(!value)throw std::runtime_error(label);}
template<class T>T take(Outcome<T> result,const StableId& label){if(!result.ok)throw std::runtime_error(label+":"+result.error.original.code);return std::move(result.value);}
V read(const fs::path& path){std::ifstream f(path);if(!f)throw std::runtime_error("missing explicit author input");std::ostringstream s;s<<f.rdbuf();return take(parse_boundary_json(s.str()),"parse input");}
StableId json(const V& value){return take(render_boundary_json(value),"render");}
void write(const fs::path& path,const V& value){std::ofstream out(path);if(!out)throw std::runtime_error("output unavailable");out<<json(value)<<'\n';}
Outcome<LiveOperationResult> query(ResidentReplaySession& world,const StableId& id,const V& args=V{V::Dict{}}){LiveOperation op;op.source=take(world.identity(),"query identity");op.payload=boundary::obj({{"query_id",V{id}},{"args",args}});return world.execute_live(op);}
bool ok(const V& value){auto* v=value.find("ok");return v&&v->as<bool>()&&*v->as<bool>();}
V command(ResidentReplaySession& world,const StableId& kind,const V& params=V{V::Dict{}},bool preview=false){auto context=take(query(world,"command_context"),"context").result;LiveOperation op;op.kind=preview?LiveOperationKind::preview:LiveOperationKind::command;op.source=take(world.identity(),"command identity");op.payload=boundary::obj({{"kind",V{kind}},{"params",params},{"actor_id",boundary::field(context,"actor_id","context")}});if(!preview){op.payload.as<V::Dict>()->emplace_back("request_seq",boundary::field(context,"next_request_seq","context"));op.payload.as<V::Dict>()->emplace_back("expected_revision",boundary::field(context,"revision","context"));}auto result=take(world.execute_live(op),kind).result;trace.push_back(boundary::obj({{"preview",V{preview}},{"command",op.payload},{"result",result}}));if(!ok(result))throw std::runtime_error(kind+":"+json(result));return result;}
void finish(ResidentReplaySession& world){for(int i=0;i<32;++i){auto a=take(query(world,"action_context"),"action").result;if(boundary::get_string(a,"action_id","action").empty())return;if(boundary::get_string(a,"action_kind","action")=="travel"){auto need=take(query(world,"journey_input_need"),"journey input").result;if(boundary::get_bool(need,"needs_input","journey"))throw std::runtime_error("actual journey requires authored input: "+json(take(query(world,"interaction_view"),"journey interaction").result));}command(world,"advance");}throw std::runtime_error("bounded action did not finish");}
void leave(ResidentReplaySession& world){auto session=take(query(world,"interaction_view"),"interaction").result;const auto phase=boundary::get_string(session,"phase","interaction");if(phase=="scene")return;command(world,phase=="trade"?"close_trade":"end_interaction");}
void move(ResidentReplaySession& world,const StableId& place){leave(world);command(world,"move_local",boundary::obj({{"place_id",V{place}}}));finish(world);}
void travel(ResidentReplaySession& world,const StableId& destination){leave(world);command(world,"travel",boundary::obj({{"destination",V{destination}}}));finish(world);}
V cards(ResidentReplaySession& world,Integer completed){const auto before=take(world.checkpoint(),"before card read");auto page=take(query(world,"actor_cards",boundary::obj({{"offset",V{Integer{0}}},{"limit",V{Integer{32}}}})),"actor cards").result;const auto& rows=boundary::array(boundary::field(page,"cards","page"),"cards");check(rows.size()==1,"author has exactly one selected PC03 card");const auto& row=rows.front();check(boundary::get_string(row,"card_id","card")=="actorlife::card.pc03"&&boundary::get_int(row,"completed_count","card")==completed,"projection counts actual settled procurement only");check((row.find("acquired")->as<std::monostate>()!=nullptr)==(completed<2),"qualification appears only after both settlements");check(before==take(world.checkpoint(),"after card read"),"card projection preserves original bank bytes");return page;}
struct Procurement {StableId role,task,offer;Integer quantity=0;};
Procurement accept(ResidentReplaySession& world,const StableId& role,const StableId& topic){leave(world);command(world,"talk",boundary::obj({{"role_id",V{role}},{"topic_id",V{topic}}}));command(world,"dialogue_next");command(world,"dialogue_choose",boundary::obj({{"option_id",V{"accept"}}}));command(world,"dialogue_confirm");finish(world);leave(world);command(world,"talk",boundary::obj({{"role_id",V{role}}}));auto page=take(query(world,"interaction_tasks"),"accepted task page").result;Procurement task;task.role=role;for(const auto& row:boundary::array(boundary::field(page,"rows","page"),"rows")){if(row.find("task_id")&&boundary::get_string(row,"status","row")!="success"&&boundary::get_string(row,"status","row")!="failed"){check(task.task.empty(),"only one active procurement for current issuer");task.task=boundary::get_string(row,"task_id","row");task.offer=boundary::get_string(row,"id","row");}}
    check(!task.task.empty(),"actual authored Need created a new accepted task");leave(world);return task;
}
void buy(ResidentReplaySession& world,Procurement& task){move(world,"society::place.grain");command(world,"talk",boundary::obj({{"role_id",V{"society::role.merchant"}}}));command(world,"dialogue_next");command(world,"dialogue_choose",boundary::obj({{"option_id",V{"trade"}}}));command(world,"dialogue_confirm");auto session=take(query(world,"interaction_view"),"merchant trade").result;check(boundary::get_string(session,"phase","session")=="trade","actual merchant dialogue opens current trade");auto page=take(query(world,"trade_view",boundary::obj({{"shop_id",V{"society::shop.grain"}},{"provider_actor_id",V{"society::actor.merchant"}}})),"procurement payer").result;StableId payer;for(const auto& row:boundary::array(boundary::field(page,"task_payers","page"),"payers"))if(boundary::get_string(row,"offer_id","payer")==task.offer)payer=boundary::get_string(row,"wallet_id","payer");check(!payer.empty(),"this accepted task supplies its actual public payer");
    // 两个正式Need的冻结数量上限均为4；真实预览仍负责不足、预算与期限拒绝。
    task.quantity=4;auto request=boundary::obj({{"shop_id",V{"society::shop.grain"}},{"item_id",V{"society::item.millet"}},{"quantity",V{task.quantity}},{"side",V{"buy"}},{"payer_wallet_id",V{payer}},{"context",boundary::field(session,"context","session")}});auto quote=command(world,"trade",request,true);request.as<V::Dict>()->emplace_back("quoted_total",boundary::field(quote,"total","quote"));request.as<V::Dict>()->emplace_back("market_revision",boundary::field(quote,"market_revision","quote"));command(world,"trade",request);finish(world);leave(world);
}
void report(ResidentReplaySession& world,const Procurement& task){leave(world);command(world,"talk",boundary::obj({{"role_id",V{task.role}}}));auto page=take(query(world,"interaction_tasks"),"current report action").result;std::optional<V> params;for(const auto& row:boundary::array(boundary::field(page,"rows","page"),"rows"))if(row.find("task_id")&&boundary::get_string(row,"task_id","row")==task.task)for(const auto& action:boundary::array(boundary::field(row,"actions","row"),"actions"))if(boundary::get_string(action,"command","action")=="report_offer")params=boundary::field(action,"params","action");check(params.has_value(),"actual issued task has a current report action");command(world,"report_offer",*params,true);command(world,"report_offer",*params);finish(world);auto completed=take(query(world,"interaction_tasks"),"terminal task").result;bool success=false;for(const auto& row:boundary::array(boundary::field(completed,"rows","page"),"rows"))if(row.find("task_id")&&boundary::get_string(row,"task_id","row")==task.task)success=boundary::get_string(row,"status","row")=="success";check(success,"real delivery and report settle successfully");}
}
int main(int argc,char** argv){fs::path output;bool created=false;try{
    if(argc!=4)throw std::runtime_error("usage: probe actual-catalog actual-request new-output");output=argv[3];if(fs::exists(output))throw std::runtime_error("output already exists; preserve prior evidence");fs::create_directories(output);created=true;auto catalog=read(argv[1]);auto world=create_resident_replay_session();auto installed=world->initialize_native(catalog,read(argv[2]));if(!installed.ok)throw std::runtime_error("actual new profile init:"+installed.error.original.code);write(output/"before.json",cards(*world,0));
    auto county=accept(*world,"society::role.city_supply","topic.city.grain");cards(*world,0);buy(*world,county);cards(*world,0);move(*world,"society::place.courtyard");report(*world,county);write(output/"after-first.json",cards(*world,1));
    travel(*world,"society::settlement.sword_yard");auto sect=accept(*world,"society::role.sect_supply","topic.sect.grain");check(sect.task!=county.task,"second procurement is a distinct actual task");cards(*world,1);travel(*world,"society::settlement.qingchuan");buy(*world,sect);cards(*world,1);move(*world,"society::place.courtyard");travel(*world,"society::settlement.sword_yard");report(*world,sect);auto final=cards(*world,2);write(output/"actor-cards.json",final);
    const auto& acquisition=boundary::field(boundary::array(boundary::field(final,"cards","page"),"cards").front(),"acquired","card");const auto& tasks=boundary::array(boundary::field(acquisition,"tasks","acquired"),"tasks");check(tasks.size()==2&&boundary::get_string(tasks[0],"task_id","task")==county.task&&boundary::get_string(tasks[1],"task_id","task")==sect.task,"qualification retains the two actual completion sources");check(!query(*world,"actor_cards",boundary::obj({{"actor_id",V{"society::actor.city_steward"}}})).ok,"current player cannot claim another actor completion page");
    auto bank=take(world->checkpoint(),"completed native bank");std::ofstream file(output/"two-procurements.hmcb",std::ios::binary);file.write(reinterpret_cast<const char*>(bank.data()),static_cast<std::streamsize>(bank.size()));file.close();auto cold=create_resident_replay_session();auto restored=cold->initialize_checkpoint(catalog,bank);check(restored.ok,"completed native bank restores without any external qualification file");auto recovered=cards(*cold,2);check(compare_boundary(boundary::field(final,"cards","page"),boundary::field(recovered,"cards","page")).exact(),"cold projection preserves original permanent sources");write(output/"cold-actor-cards.json",recovered);write(output/"commands.json",V{trace});write(output/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{checks}},{"first_task_id",V{county.task}},{"second_task_id",V{sect.task}},{"tick",V{take(world->identity(),"terminal identity").tick}},{"main_tested",V{false}}}));std::cout<<"ACTOR_CARD_PROCUREMENT_LIVE "<<checks<<" checks 0 failures; two actual procurement settlements and native cold recovery\n";return 0;
}catch(const std::exception& e){if(created){write(output/"failed-commands.json",V{trace});write(output/"failure.json",boundary::obj({{"ok",V{false}},{"message",V{StableId{e.what()}}}}));}std::cerr<<"ACTOR_CARD_PROCUREMENT_LIVE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
